1	package cli
2	
3	import (
4		"context"
5		"encoding/json"
6		"fmt"
7		"os"
8		"path/filepath"
9		"sort"
10		"strconv"
11		"strings"
12		"time"
13	)
14	
15	const factsProposalsFileName = "proposals.ndjson"
16	
17	func factsProposalsRelPath(branch string) string {
18		return filepath.ToSlash(filepath.Join(factsBranchRelDir(branch), factsProposalsFileName))
19	}
20	
21	// loadFactProposals reads a branch's pending proposals; a missing file yields
22	// none. A malformed line is a hard error so a corrupt queue is surfaced.
23	func loadFactProposals(brainDir, branch string) ([]factProposal, error) {
24		path := filepath.Join(brainDir, filepath.FromSlash(factsProposalsRelPath(branch)))
25		data, err := os.ReadFile(path)
26		if err != nil {
27			if os.IsNotExist(err) {
28				return nil, nil
29			}
30			return nil, err
31		}
32		var proposals []factProposal
33		for i, line := range strings.Split(string(data), "\n") {
34			line = strings.TrimSpace(line)
35			if line == "" {
36				continue
37			}
38			var p factProposal
39			if err := json.Unmarshal([]byte(line), &p); err != nil {
40				return nil, fmt.Errorf("parse %s line %d: %w", factsProposalsRelPath(branch), i+1, err)
41			}
42			proposals = append(proposals, p)
43		}
44		return proposals, nil
45	}
46	
47	// writeFactProposals persists a branch's pending proposals, deduplicated by
48	// (action, candidate, target) and sorted for a stable file. An empty set
49	// removes the file so a fully-resolved branch leaves no stale queue.
50	func writeFactProposals(brainDir, branch string, proposals []factProposal) error {
51		deduped := dedupeProposals(proposals)
52		path := filepath.Join(brainDir, filepath.FromSlash(factsProposalsRelPath(branch)))
53		if len(deduped) == 0 {
54			if err := os.Remove(path); err != nil && !os.IsNotExist(err) {
55				return err
56			}
57			return nil
58		}
59		var buf strings.Builder
60		for _, p := range deduped {
61			data, err := json.Marshal(p)
62			if err != nil {
63				return err
64			}
65			buf.Write(data)
66			buf.WriteByte('\n')
67		}
68		dir := filepath.Join(brainDir, filepath.FromSlash(factsBranchRelDir(branch)))
69		if err := os.MkdirAll(dir, 0o700); err != nil {
70			return err
71		}
72		return writeFileAtomic(path, []byte(buf.String()), 0o600)
73	}
74	
75	func dedupeProposals(proposals []factProposal) []factProposal {
76		seen := make(map[string]struct{}, len(proposals))
77		out := make([]factProposal, 0, len(proposals))
78		for _, p := range proposals {
79			key := p.Action + "\x00" + p.CandidateID + "\x00" + p.TargetID
80			if _, ok := seen[key]; ok {
81				continue
82			}
83			seen[key] = struct{}{}
84			out = append(out, p)
85		}
86		sort.SliceStable(out, func(i, j int) bool {
87			if out[i].TargetID != out[j].TargetID {
88				return out[i].TargetID < out[j].TargetID
89			}
90			return out[i].CandidateID < out[j].CandidateID
91		})
92		return out
93	}
94	
95	const (
96		// maxReconcileExisting bounds how many existing active facts at a
97		// candidate's paths are shown to the agent, keeping the reconcile prompt
98		// bounded even on busy paths. When more exist, the most recently updated
99		// are shown and the cap is reported as a warning (no silent truncation).
100		maxReconcileExisting = 50
101	)
102	
103	// reconcilePrompt is the static system prompt for the reconcile pass. The
104	// dynamic candidate/existing lists are supplied on stdin (see reconcileInput).
105	// Like the distill prompt it must not begin with a dash — the agent runners
106	// pass it as a positional CLI argument.
107	func reconcilePrompt() string {
108		return `You are deduplicating durable repository facts. On stdin you receive two
109	numbered lists: CANDIDATES (new facts just extracted from a session) and
110	EXISTING (facts already stored at the same taxonomy paths). For each candidate,
111	decide how it relates to the existing facts.
112	
113	For every candidate output exactly one line, in candidate-number order:
114	
115	    <candidate#> <decision> <existing#-or-dash> <confidence>
116	
117	- <candidate#>: the candidate's number.
118	- <decision>: one of
119	    new        — not represented by any existing fact.
120	    merge       — the SAME meaning as an existing fact (a restatement); consolidate.
121	    supersede   — CONTRADICTS or replaces an existing fact (the candidate is newer/correct).
122	- <existing#-or-dash>: for merge/supersede, the EXISTING fact number it refers
123	  to; for new, a dash "-".
124	- <confidence>: 0.00 to 1.00, your confidence in a merge/supersede decision
125	  (use 1.0 for new).
126	
127	Rules:
128	- A restatement ("use tabs") and a reversal ("use spaces") look similar but are
129	  NOT the same: the first is merge, the second is supersede. Read the meaning.
130	- When unsure between merge/supersede and new, prefer new with lower confidence
131	  rather than wrongly collapsing distinct facts.
132	- Output only these lines. No prose, no headers, no blank lines.
133	
134	Example:
135	1 new - 1.0
136	2 merge 3 0.88
137	3 supersede 1 0.93`
138	}
139	
140	// reconcileInput renders the candidate and existing fact lists for stdin. Both
141	// are numbered 1-based; the agent refers to them by number, and the parser maps
142	// those numbers back to records (existing numbers resolve to fact ids).
143	func reconcileInput(candidates, existing []factRecord) []byte {
144		var b strings.Builder
145		b.WriteString("CANDIDATES\n")
146		for i, c := range candidates {
147			fmt.Fprintf(&b, "%d [%s] %s\n", i+1, strings.Join(c.Paths, ","), c.Text)
148		}
149		b.WriteString("\nEXISTING\n")
150		for i, e := range existing {
151			fmt.Fprintf(&b, "%d [%s] %s\n", i+1, strings.Join(e.Paths, ","), e.Text)
152		}
153		return []byte(b.String())
154	}
155	
156	// parseReconcileActions turns the agent's decision lines into factActions. Each
157	// candidate gets exactly one action: a line that is missing, malformed, or
158	// references an out-of-range existing fact degrades that candidate to `new`
159	// (with a warning) so a parser hiccup never drops a fact or misapplies a
160	// merge/supersede.
161	func parseReconcileActions(output string, candidates, existing []factRecord) ([]factAction, []string) {
162		decided := make(map[int]factAction, len(candidates))
163		var warnings []string
164	
165		for _, raw := range strings.Split(output, "\n") {
166			line := strings.TrimSpace(raw)
167			if line == "" {
168				continue
169			}
170			fields := strings.Fields(line)
171			// Need at least "<candidate#> <decision>". The canonical form is
172			// "<candidate#> <decision> <existing#-or-dash> <confidence>", but lighter
173			// models (gpt-5.3-codex-spark) drop the "-" placeholder for new
174			// ("3 new 1.0") or omit a trailing confidence; handle those per kind below
175			// instead of rejecting the whole line.
176			if len(fields) < 2 {
177				warnings = append(warnings, "reconcile: malformed line: "+truncateString(line, 80))
178				continue
179			}
180			ci, err := strconv.Atoi(fields[0])
181			if err != nil || ci < 1 || ci > len(candidates) {
182				warnings = append(warnings, "reconcile: bad candidate number: "+truncateString(line, 80))
183				continue
184			}
185			candidate := candidates[ci-1]
186			kind := strings.ToLower(fields[1])
187			switch kind {
188			case factActionNew:
189				// Tolerate a missing "-" placeholder. Confidence is the last field when
190				// it is numeric; otherwise default to 1.0 (the prompt's value for new).
191				confidence := 1.0
192				if len(fields) >= 3 {
193					if last := fields[len(fields)-1]; isNumericToken(last) {
194						confidence = parseConfidence(last)
195					}
196				}
197				decided[ci] = factAction{Kind: factActionNew, Confidence: confidence, Candidate: candidate}
198			case factActionMerge, factActionSupersede:
199				if len(fields) < 3 {
200					warnings = append(warnings, fmt.Sprintf("reconcile: %s missing existing number, treating candidate %d as new", kind, ci))
201					decided[ci] = factAction{Kind: factActionNew, Confidence: 1.0, Candidate: candidate}
202					continue
203				}
204				ei, eerr := strconv.Atoi(fields[2])
205				if eerr != nil || ei < 1 || ei > len(existing) {
206					warnings = append(warnings, fmt.Sprintf("reconcile: %s with bad existing number, treating candidate %d as new", kind, ci))
207					decided[ci] = factAction{Kind: factActionNew, Confidence: 1.0, Candidate: candidate}
208					continue
209				}
210				// A missing confidence stays 0 so the action is queued for review
211				// rather than auto-applied.
212				confidence := 0.0
213				if len(fields) >= 4 {
214					confidence = parseConfidence(fields[3])
215				}
216				decided[ci] = factAction{Kind: kind, TargetID: existing[ei-1].ID, Confidence: confidence, Candidate: candidate}
217			default:
218				warnings = append(warnings, "reconcile: unknown decision: "+truncateString(line, 80))
219			}
220		}
221	
222		actions := make([]factAction, 0, len(candidates))
223		for i, candidate := range candidates {
224			if action, ok := decided[i+1]; ok {
225				actions = append(actions, action)
226				continue
227			}
228			warnings = append(warnings, fmt.Sprintf("reconcile: no decision for candidate %d, treating as new", i+1))
229			actions = append(actions, factAction{Kind: factActionNew, Confidence: 1.0, Candidate: candidate})
230		}
231		return actions, warnings
232	}
233	
234	// isNumericToken reports whether a token parses as a float, used to tell a
235	// trailing confidence value apart from a "-" placeholder or missing field.
236	func isNumericToken(token string) bool {
237		_, err := strconv.ParseFloat(token, 64)
238		return err == nil
239	}
240	
241	// parseConfidence reads a confidence token, clamped to [0,1]; unparseable
242	// values default to 0 so an unreadable confidence is treated as low (and thus
243	// queued for review rather than auto-applied).
244	func parseConfidence(token string) float64 {
245		value, err := strconv.ParseFloat(token, 64)
246		if err != nil {
247			return 0
248		}
249		if value < 0 {
250			return 0
251		}
252		if value > 1 {
253			return 1
254		}
255		return value
256	}
257	
258	// activeFactsAtPaths returns the active facts whose paths intersect the given
259	// path set, most-recently-updated first, capped at maxReconcileExisting. The
260	// boolean reports whether the cap dropped any facts.
261	func activeFactsAtPaths(records []factRecord, paths []string) ([]factRecord, bool) {
262		want := make(map[string]struct{}, len(paths))
263		for _, p := range paths {
264			want[p] = struct{}{}
265		}
266		var matched []factRecord
267		for _, record := range records {
268			if record.Status != factStatusActive {
269				continue
270			}
271			for _, p := range record.Paths {
272				if _, ok := want[p]; ok {
273					matched = append(matched, record)
274					break
275				}
276			}
277		}
278		sort.SliceStable(matched, func(i, j int) bool {
279			if !matched[i].UpdatedAt.Equal(matched[j].UpdatedAt) {
280				return matched[i].UpdatedAt.After(matched[j].UpdatedAt)
281			}
282			return matched[i].ID < matched[j].ID
283		})
284		if len(matched) > maxReconcileExisting {
285			return matched[:maxReconcileExisting], true
286		}
287		return matched, false
288	}
289	
290	// candidatePathSet returns the sorted union of paths across the candidates.
291	func candidatePathSet(candidates []factRecord) []string {
292		seen := map[string]struct{}{}
293		for _, c := range candidates {
294			for _, p := range c.Paths {
295				seen[p] = struct{}{}
296			}
297		}
298		paths := make([]string, 0, len(seen))
299		for p := range seen {
300			paths = append(paths, p)
301		}
302		sort.Strings(paths)
303		return paths
304	}
305	
306	// reconcileChunkCandidates resolves a chunk's candidates against the current
307	// active set: when no existing facts share the candidates' paths, every
308	// candidate is trivially `new` (no agent call); otherwise the agent decides.
309	// An agent error falls back to treating all candidates as `new` so facts are
310	// never lost. It returns the actions to apply plus any warnings.
311	func reconcileChunkCandidates(ctx context.Context, run distillAgentRunner, agentArgs []string, candidates, active []factRecord, repoDir string, timeout time.Duration) ([]factAction, []string) {
312		existing, capped := activeFactsAtPaths(active, candidatePathSet(candidates))
313		if len(existing) == 0 {
314			actions := make([]factAction, len(candidates))
315			for i, c := range candidates {
316				actions[i] = factAction{Kind: factActionNew, Confidence: 1.0, Candidate: c}
317			}
318			return actions, nil
319		}
320		var warnings []string
321		if capped {
322			warnings = append(warnings, fmt.Sprintf("reconcile: more than %d existing facts at these paths; comparing against the %d most recent", maxReconcileExisting, maxReconcileExisting))
323		}
324		out, err := run(ctx, repoDir, agentArgs, reconcileInput(candidates, existing), timeout)
325		if err != nil {
326			warnings = append(warnings, fmt.Sprintf("reconcile agent failed, treating %d candidates as new: %v", len(candidates), err))
327			actions := make([]factAction, len(candidates))
328			for i, c := range candidates {
329				actions[i] = factAction{Kind: factActionNew, Confidence: 1.0, Candidate: c}
330			}
331			return actions, warnings
332		}
333		actions, parseWarnings := parseReconcileActions(out, candidates, existing)
334		return actions, append(warnings, parseWarnings...)
335	}
