364	
365		for branch, records := range byBranch {
366			if err := writeFacts(brainDir, branch, records); err != nil {
367				return nil, err
368			}
369			// Union this run's proposals with any already queued (a --force rebuild
370			// starts fresh since it rebuilds the distilled facts), then persist.
371			var prior []factProposal
372			if !distillOpts.force {
373				if loadedProposals, loadErr := loadFactProposals(brainDir, branch); loadErr != nil {
374					warnings = append(warnings, fmt.Sprintf("load proposals for %s: %v", branch, loadErr))
375				} else {
376					prior = loadedProposals
377				}
378			}
379			merged := dedupeProposals(append(prior, proposalsByBranch[branch]...))
380			if err := writeFactProposals(brainDir, branch, merged); err != nil {
381				return nil, err
382			}
383		}
384		if err := writeFactTaxonomy(brainDir, taxonomy); err != nil {
385			return nil, err
386		}
387		saveDistillCache(brainDir, newCache)
388	
389		// Summarize the manifest from the whole on-disk store, not just the branches
390		// touched this run. A branch-limited (`--branch`) or incremental run only
391		// loads a subset into byBranch; folding that subset into the manifest would
392		// drop counts/branches/proposals for facts that still exist on other
393		// branches. Re-reading the store after writing keeps sources.facts whole.
394		allBranches, err := loadAllFactBranches(brainDir)
395		if err != nil {
396			return nil, err
397		}
398		branchNames := make([]string, 0, len(allBranches))
399		for branch := range allBranches {
400			branchNames = append(branchNames, branch)
401		}
402		totalProposals := countFactProposals(brainDir, branchNames)
403	
404		source := summarizeFactSource(now, allBranches, chunksScanned, chunksDistilled, totalProposals, warnings)
405		if manifest.Sources == nil {
406			manifest.Sources = &brainSources{}
407		}
408		manifest.Sources.Facts = source
409		if manifest.GeneratedAt.IsZero() {
410			manifest.GeneratedAt = now
411		}
412		if err := writeBrainManifestAndReadme(brainDir, *manifest); err != nil {
413			return nil, err
414		}
415		return source, nil
416	}
417	
418	// preprocessTranscriptForDistill strips tool calls and tool outputs (plus
419	// session/meta records) from a JSONL transcript before chunking, leaving only the
420	// human and assistant conversation text that the quality gate actually mines for
421	// facts. Each input line maps to exactly one output line: a dropped record
422	// becomes a blank line, which chunkTranscript skips while still incrementing the
423	// line counter, so a distilled fact's provenance anchor keeps pointing at the
424	// correct line in the original transcript. Lines that are not JSON objects (for
425	// example an already-rendered/compact transcript) are passed through unchanged so
426	// the preprocessor is safe for any transcript format.
427	func preprocessTranscriptForDistill(content string) string {
428		lines := strings.Split(content, "\n")
429		for i, line := range lines {
430			if strings.TrimSpace(line) == "" {
431				lines[i] = ""
432				continue
433			}
434			var obj map[string]any
435			if err := json.Unmarshal([]byte(line), &obj); err != nil {
436				continue // not JSONL; leave the line as-is
437			}
438			// Collapse the kept text onto a single line so one record stays one line
439			// and the line numbering (provenance) is preserved.
440			lines[i] = strings.Join(strings.Fields(distillConversationText(obj)), " ")
441		}
442		return strings.Join(lines, "\n")
443	}
444	
445	// distillConversationText returns the human/assistant text worth distilling from
446	// one transcript record, or "" for tool calls, tool outputs, reasoning, and
447	// session/meta records. It mirrors the record routing in
448	// extractHistoryJSONFragments (codex `event_msg`/`response_item` and Claude
449	// `assistant`/`user` shapes) but deliberately keeps user turns — where standing
450	// rules and preferences live — and discards everything tool-related.
451	func distillConversationText(obj map[string]any) string {
452		switch jsonString(obj["type"]) {
453		case "agent_message":
454			return jsonString(obj["message"])
455		case "event_msg":
456			payload := jsonMap(obj["payload"])
457			switch jsonString(payload["type"]) {
458			case "agent_message", "user_message":
459				return jsonString(payload["message"])
460			case "task_complete":
461				return jsonString(payload["last_agent_message"])
462			}
463			return "" // task_started, exec_command_end, patch_apply_end, ...
464		case "response_item":
465			payload := jsonMap(obj["payload"])
466			if jsonString(payload["type"]) != "message" {
467				return "" // function_call, custom_tool_call, function_call_output, reasoning
468			}
469			if role := jsonString(payload["role"]); role != "assistant" && role != "user" {
470				return ""
471			}
472			return distillTextBlocks(payload["content"])
473		case "assistant", "user":
474			return distillTextBlocks(jsonMap(obj["message"])["content"])
475		case "session_meta", "turn_context", "permission-mode", "progress":
476			return ""
477		default:
478			return jsonString(obj["message"])
479		}
480	}
481	
482	// distillTextBlocks pulls plain text out of a message "content" field, keeping
483	// text blocks and dropping tool_use / tool_result blocks. content may be a plain
484	// string (a bare user/assistant message) or an array of typed blocks.
485	func distillTextBlocks(content any) string {
486		switch value := content.(type) {
487		case string:
488			return value
489		case []any:
490			var parts []string
491			for _, item := range value {
492				block := jsonMap(item)
493				if len(block) == 0 {
494					continue
495				}
496				switch jsonString(block["type"]) {
497				case "tool_use", "tool_result":
498					continue // tool call / tool output
499				default:
500					if text := firstNonEmptyString(block["text"], block["input_text"], block["output_text"], block["content"]); text != "" {
501						parts = append(parts, text)
502					}
503				}
504			}
505			return strings.Join(parts, " ")
506		default:
507			return ""
508		}
509	}
510	
511	// chunkTranscript splits a transcript into line-numbered chunks no larger than
512	// maxBytes (measured on the rendered, line-numbered text). A single line that
513	// exceeds maxBytes still becomes its own chunk rather than being dropped, so no
514	// content is silently lost. Blank input yields no chunks.
515	func chunkTranscript(content string, maxBytes int) []transcriptChunk {
516		if maxBytes <= 0 {
517			maxBytes = defaultDistillChunkSize
518		}
519		lines := strings.Split(content, "\n")
520		var chunks []transcriptChunk
521		var buf strings.Builder
522		startLine := 0
523		lineNo := 0
524		flush := func(endLine int) {
525			if buf.Len() == 0 {
526				return
527			}
528			chunks = append(chunks, transcriptChunk{StartLine: startLine, EndLine: endLine, Text: buf.String()})
529			buf.Reset()
530			startLine = 0
531		}
532		for _, line := range lines {
533			lineNo++
534			if strings.TrimSpace(line) == "" {
535				continue
536			}
537			rendered := fmt.Sprintf("%d\t%s\n", lineNo, line)
538			if buf.Len() > 0 && buf.Len()+len(rendered) > maxBytes {
539				flush(lineNo - 1)
540			}
541			if buf.Len() == 0 {
542				startLine = lineNo
543			}
544			buf.WriteString(rendered)
545		}
546		flush(lineNo)
547		return chunks
548	}
549	
550	// distillSessionFingerprint is the incremental-skip signal for one session. It
551	// hashes the session identity (id, latest checkpoint, transcript path, resolved
552	// branch) together with a digest of the transcript bytes, so any content change
553	// — even one that keeps the same checkpoint, such as a compact↔raw re-export or
554	// an exporter fix — invalidates the cache and forces a re-distill. The branch is
555	// the *resolved* one the facts are written under (session.Branch may be empty
556	// and fall back to the manifest default), so a default-branch change re-keys the
557	// session instead of letting a stale cache skip it.
558	func distillSessionFingerprint(session exportSession, branch, content string) string {
559		contentSum := sha256.Sum256([]byte(content))
560		sum := sha256.Sum256([]byte(strings.Join([]string{
561			session.SessionID,
562			session.LatestCheckpoint,
563			filepath.ToSlash(session.TranscriptPath),
564			branch,
565			hex.EncodeToString(contentSum[:]),
566		}, "\x00")))
567		return "sha256:" + hex.EncodeToString(sum[:])
568	}
569	
570	// readBrainRelativeFile reads a brain-relative path, rejecting absolute paths
571	// and parent-directory escapes so a manifest-supplied path cannot read outside
572	// the brain directory.
573	func readBrainRelativeFile(brainDir, rel string) (string, error) {
574		clean := filepath.Clean(filepath.FromSlash(rel))
575		if filepath.IsAbs(clean) || clean == ".." || strings.HasPrefix(clean, ".."+string(filepath.Separator)) {
576			return "", fmt.Errorf("unsafe transcript path: %s", rel)
577		}
578		data, err := os.ReadFile(filepath.Join(brainDir, clean))
579		if err != nil {
580			return "", err
581		}
582		return string(data), nil
583	}
584	
585	// loadDistillCache reads the incremental cache, always returning a usable value:
586	// any read/parse error or version mismatch yields an empty cache so the next
587	// run simply re-distills everything.
588	func loadDistillCache(brainDir string) distillCache {
589		empty := distillCache{Version: distillCacheVersion, Sessions: map[string]string{}}
590		data, err := os.ReadFile(filepath.Join(brainDir, filepath.FromSlash(distillCachePath)))
591		if err != nil {
592			return empty
593		}
594		var cache distillCache
595		if err := json.Unmarshal(data, &cache); err != nil || cache.Version != distillCacheVersion || cache.Sessions == nil {
596			return empty
597		}
598		return cache
599	}
600	
601	// saveDistillCache persists the incremental cache. Failure is non-fatal: a
602	// missing cache only costs a full re-distillation next run.
603	func saveDistillCache(brainDir string, cache distillCache) {
604		data, err := json.MarshalIndent(cache, "", "  ")
605		if err != nil {
606			return
607		}
608		dir := filepath.Join(brainDir, factsDirName)
609		if err := os.MkdirAll(dir, 0o700); err != nil {
610			return
611		}
612		_ = writeFileAtomic(filepath.Join(brainDir, filepath.FromSlash(distillCachePath)), append(data, '\n'), 0o600)
613	}
614	
615	// execDistillAgent is the real distillAgentRunner: it runs the agent with the
616	// transcript chunk on stdin and returns stdout, bounded by a timeout and an
617	// output-size cap.
618	func execDistillAgent(ctx context.Context, dir string, args []string, input []byte, timeout time.Duration) (string, error) {
619		if len(args) == 0 {
620			return "", errors.New("distill: empty agent command")
621		}
622		runCtx, cancel := context.WithTimeout(ctx, timeout)
623		defer cancel()
624		command := exec.CommandContext(runCtx, args[0], args[1:]...)
625		command.Dir = dir
626		command.Stdin = bytes.NewReader(input)
627		var stdout, stderr bytes.Buffer
628		command.Stdout = &stdout
629		command.Stderr = &stderr
630		err := command.Run()
631		if errors.Is(runCtx.Err(), context.DeadlineExceeded) {
632			return "", fmt.Errorf("agent timed out after %s", timeout)
633		}
634		if err != nil {
635			warning := strings.TrimSpace(stderr.String())
636			if warning == "" {
637				warning = strings.TrimSpace(stdout.String())
638			}
639			return "", fmt.Errorf("agent failed: %w: %s", err, truncateAgentWarning(warning))
640		}
641		if stdout.Len() > distillMaxOutputBytes {
642			return "", fmt.Errorf("agent output exceeds %d bytes", distillMaxOutputBytes)
643		}
644		return stdout.String(), nil
645	}
646

